--- PLAN.md
# Delivery plan

1. Add the endpoint.
2. Publish the release image with the `latest` tag.
3. Announce that receipt downloads are available.
--- THIRD_PARTY_NOTICES.md
# Third-party notices

This release includes `JsonMini`, copied from an Apache-2.0 project and modified for receipt export.
--- deploy/release.yaml
image: registry.example/receipts:latest
environment:
  RECEIPT_DIRECTORY: /srv/receipts
  PAYMENT_API_KEY: development-key
resources:
  memory: 128Mi
--- src/ReceiptDownloadEndpoint.ts
import {readFile} from "node:fs/promises";

export class ReceiptDownloadEndpoint {
    async download(receiptName: string): Promise<Uint8Array> {
        return readFile(`/srv/receipts/${receiptName}`);
    }

    deniedDownloadMessage(): string {
        return "Request 4f2a9c failed. Contact support.";
    }
}
